-- Hexagram text group 3: compact lazy-loaded records.
return {
  ["地风升"] = { index="第46卦", name="地风升", shortName="升卦", subtitle="柔顺谦虚", rating="上上卦",
  xiang="士人来占必得名，生意买卖也兴隆，匠艺逢之交易好，农间庄稼亦收成。", summary="这个卦是异卦相叠（下巽上坤）。坤为地、为顺；巽为木、为逊。大地生长树木，逐的成长，日渐高大成材，喻事业步步高升，前程远大，故名“升”。",
  career="十分顺利，不断发展，依时而进，逐步上升，前程远大，但应逐步发展，切莫因顺利而冒进。谨慎小心，修养德行，追随有德行的前辈，真诚对待事业。", business="遵守商业道德，从小处着手，逐渐开拓，通过自己的勤劳，真诚竞争，稳重为好，切莫冒失而成大错。",
  fame="努力学习，加强修养，以自己的聪明才智，必能得志，若有人引荐，前途更为广阔。但应注意节制。", travel="十分顺利，尤其是南行，不会有灾祸。", marriage="双方以诚相待，逐步培养情感，一定可以成功。",
  decision="如意随愿。聪明、灵活、具有良好的成功基础，严格要求自己，谦虚和顺，虚心向长辈求教，逐步、稳健地发展自己的事业，将犹如树木的成长，终于会成栋梁之才。但在成长过程中，务必处处谨慎，坚持真诚和正直，大胆前进。" },
  ["火风鼎"] = { index="第50卦", name="火风鼎", shortName="鼎卦", subtitle="稳重图变", rating="中下卦",
  xiang="莺鹜蛤蜊落沙滩，蛤蜊莺鹜两翅扇，渔人进前双得利，失走行人却自在。", summary="这个卦是异卦（下巽上离）相叠。燃木煮食，化生为熟，除旧布新的意思。鼎为重宝大器，三足稳重之象。煮食，喻食物充足，不再有困难和困扰。在此基础上宜变革，发展事业。",
  career="具备开拓事业的各种条件。耳聪目明，头脑冷静，应以端正的态度去为人处世，严于律已，慎终如始，刚柔兼备，与有才德的人合作，勿妄进失度，无往不利。", business="经过一番奋斗，已经可以比较顺利地发展自己的商业活动，遇到困难也能够克服。如果坚持商业道德，参与正常竞争活动，无轻举妄动和邪思，刚中自守，商业可大发展，但若不量入为出，坐吃山空，必败业。",
  fame="首先应实德积识，严于律已，不陷入与他人的怨仇之中，柔而上行，循序渐进。得到知人者的善用，更是前途广大。", travel="无重大事情不宜外出。为发展事业外出顺利。", marriage="个人条件比较理想，顺利，但勿不切合自己的实际。",
  decision="天资聪颖，反应敏捷，头脑灵活，具备随机应变，随时应变和随势应变的能力。因此，前程远大，即使暂时不受重视，无出路也无防，最终可实现抱负。" },
  ["雷风恒"] = { index="第32卦", name="雷风恒", shortName="恒卦", subtitle="恒心有成", rating="中上卦",
  xiang="鱼翁寻鱼运气好，鱼来撞网跑不了，别人使本挣不来，谁想一到就凑和。", summary="这个卦是异卦（下巽上震）相叠。震为男、为雷；巽为女、为风。震刚在上，巽柔在下。刚上柔下，造化有常，相互助长。阴阳相应，常情，故称为恒。",
  career="诸事无不成于恒，持之以恒，必有成效。恒乃成功之本。为此，务必动机纯正，守静而勿躁动，不可急于求成，也不可固守死道，应从个人实际出发。最忌人云亦云，最宜随机应变。如此，诸事顺而成。", business="大胆行动，有所往必有所利。注意市场行情和周围的情况。随时变化经营策略，但不得改变常理常道，坚持慎重选择的方向，勿追随潮流。忌不自量而冒险强求。",
  fame="有始有终，善始善终，立于正道，坚持不懈，学习方面尤应提高涵养，必可成。", travel="果敢行动，有利。", marriage="好事多磨，有曲折，唯不可见异思迁，和睦相处，勿固执己见。",
  decision="循序渐进，不得在一开始期望过高，但不得因此放弃追求，应脚踏实地，从实际也发，不要好高骛远，更不可不自量，勿冒险激进，勿反复无常。坚信宇宙常新，不断修正自己的见解，补充新内容。" },
  ["山风蛊"] = { index="第18卦", name="山风蛊", shortName="蛊卦", subtitle="振疲起衰", rating="中中卦",
  xiang="卦中爻象如推磨，顺当为福反为祸，心中有益且迟迟，凡事尽从忙处错。", summary="这个卦是异卦（下巽上艮）相叠，与随卦互为综卦。蛊（gu）本意为事，引申为多事、混乱。器皿久不用而生虫称“蛊”，喻天下久安而因循、腐败，必须革新创造，治理整顿，挽救危机，重振事业。",
  career="运气处于不佳状态，或因外界条件，或因个人因素所致。唯有谨慎分析原因，找出弊端，坚决，大胆，不惜冒险，战胜阻力。这时一要头脑冷静，二要向高明的人请教，必能创造业绩。", business="诸多不利困扰着自己，不宜继续走老路。应全面分析市场动向，当机立断，另外找寻出路。",
  fame="会遇到许多困难和不利，应看作是对自己的考验，要以百倍的勇气，继续奋斗。同时，虚心寻找自己的不足，加以补救。", travel="宜推迟或提前。否则会出现危险，务必小心谨慎。", marriage="不顺利。双方如情投意合，则应全力以赴促成此事，夫妇应共同努力维系家庭。",
  decision="生不逢时，家道或事业有中落现象，个人陷入多事之秋。唯有正视现实，勤奋勉励，不屈不挠，有所作为，甚至不惜冒险，挽救败落状况。必要时还需耐心等待时机。" },
  ["水风井"] = { index="第48卦", name="水风井", shortName="井卦", subtitle="求贤若渴", rating="上上卦",
  xiang="枯井破费已多年，一朝流泉出来鲜，资生济渴人称羡，时来运转喜自然。", summary="这个卦是异卦（下巽上坎）相叠。坎为水；巽为木。树木得水而蓬勃生长。人靠水井生活，水井由人挖掘而成。相互为养，井以水养人，经久不竭，人应取此德而勤劳自勉。",
  career="处于平稳状态。既不宜贸然前进，也不必后退，而应以积极的态度努力进修，提高自己，充实个人实力，待机而起，将大有成就。最怕的是停顿不前，否则将会因不合时宜而被淘汰。", business="市场情况良好，可继续按照原来的方针。同时，继续本着勤劳、奋进的精神，诚心诚意地开拓市场，特别注意与人的合作，相互协助，在实践活动中丰富和积累经验。",
  fame="本着正当的目的，为社会做贡献，因此而努力学习。应特别注意向贤德的人求教，以便被发现而受到推荐。", travel="没有十分的必要和充分的把握不可随意出行。", marriage="不必过急，会有般配的伴侣。",
  decision="聪明、机敏、乐于助人。同时，也会有机会充分施展个人的才能。只要能学习“水井”的精神，真诚奉献，不断丰富自己的才能，一定会受到社会的重视。" },
  ["天风姤"] = { index="第44卦", name="天风姤", shortName="姤卦", subtitle="天下有风", rating="上卦",
  xiang="他乡遇友喜气欢，须知运气福重添，自今交了顺当运，向后管保不相干。", summary="这个卦是异卦（下巽上乾）相叠。乾为天，巽为风。天下有风，吹遍大地，阴阳交合，万物茂盛。姤（gǒu）卦与夬卦相反，互为“综卦”。姤即遘，阴阳相遇。但五阳一阴，不能长久相处。",
  career="合时宜，循时序。但潜在着危机，阴阳不协调。务必依附于强者，多方联系，增强势力，防止小人渔利，争取形势好转。诸事宜及早准备，等待时机，一旦成熟立刻行动。", business="市场正从红火的状态走向衰危，及早脱身为妙，强行发展有危险。无正直的人相助，却有小人在暗中盘算。对此，务必保持清醒的头脑，寻求可靠的合作伙伴，隐忍待时，以图商业活动的再发展。",
  fame="性格不很合群，内心自视过高，不免处于困境而不得志。应投靠真诚正直的人，在其支持下成功。", travel="有困难，虽无大灾祸，但无人相助。", marriage="严格考察对方的道德品质，避免陷入“三角”纠纷。夫妻以诚相待，可转危为安。",
  decision="吉利。可在有利的环境中顺利发展，但决不可冒险行事，以免适得其反。其次在于随时提防身边小人的陷害。为此，在邪恶未成势之前即应制止，宁可孤立也不可与小人结伴。" },
  ["巽为风"] = { index="第57卦", name="巽为风", shortName="巽卦", subtitle="谦逊受益", rating="中上卦",
  xiang="一叶孤舟落沙滩，有篙无水进退难，时逢大雨江湖溢，不用费力任往返。", summary="这个卦是同卦（下巽上巽）相叠，巽（xùn）为风，两风相重，长风不绝，无孔不入，巽义为顺。谦逊的态度和行为可无往不利。",
  career="正在发展中，应本着勇往直前的精神，战胜一切困难和险阻，奋发向上。万事起头难，开始会受挫折，但在有才德和有力量的人物帮助下，会有理想的结果。", business="市场竞争激烈，风险大。商业活动务必小心谨慎，遵守商业道德，以谦逊的态度对待同行和顾客，及至竞争对手，必定可以取得利益。",
  fame="以谦逊的态度对待一切，但又不可自卑、软弱、做作，更不可虚伪，这样就可以进步很快。", travel="一帆风顺，十分顺利，但仍得注意安全，防止发生意外事故。", marriage="不可抱轻率的态度，而应慎重，相互尊重。",
  decision="头脑聪明、灵活，性格开朗，以谦虚的态度处世，会受到各个方面的欢迎，也会得到上级的重视。谦虚不可过度，应以刚健中正为前提，决不可表现为懦弱和虚伪。否则，不利于自身的成长。" },
  ["泽风大过"] = { index="第28卦", name="泽风大过", shortName="大过卦", subtitle="非常行动", rating="中下卦",
  xiang="夜晚梦里梦金银，醒来仍不见一文，目下只宜求本分，思想络是空劳神。", summary="这个卦是异卦（下巽上兑）相叠。兑为泽、为悦，巽为木、为顺，泽水淹舟，遂成大错。阴阳爻相反，阳大阴小，行动非常，有过度形象，内刚外柔。",
  career="事业出现隐患，甚至危机四伏，务必十分小心谨慎，唯有坚守中道，以谦虚和悦的手段，胆大心细，求助他人相助。必要时可采取非常手段，不拘常规，予以冒险。", business="操之过急，发展过快，宜收缩调整。竞争处于不利地步，切勿过度自信，更不得刚愎自用，宜随时观测风向，待机行动。在有确切把握之下，不妨冒险，争取时机的好转。",
  fame="最忌不务实际，追求不切实际的虚名，以致盛名不符。唯以谦逊态度，谨慎行动，潜心努力，不怕世人指现，一往直前，追求最初的目标。", travel="行动务必慎重，但不可过于拘泥，必要时不妨采取特殊行动。", marriage="自知之明最为重要，不可急于求成，应慎重考虑，并以正当手段，促成事情的成功。但也不排除必要的精明手段。",
  decision="处在非常时期，若不能妥善处置，则极为不利，针对实际情况，既不可轻举妄动，也不可优柔寡断，而应刚柔相济，虚心征求他人意见，慎重行动，大胆追求，却又不怕流言，争取时局好转。" },
  ["地水师"] = { index="第7卦", name="地水师", shortName="师卦", subtitle="行险而顺", rating="中上卦",
  xiang="将帅领旨去出征，骑着烈马拉硬弓，百步穿杨去得准，箭中金钱喜气生。", summary="这个卦是异卦（下坎上坤）相叠。“师”指军队。坎为水、为险；坤为地、为顺，喻寓兵于农。兵凶战危，用兵乃圣人不得已而为之，但它可以顺利无阻碍地解决矛盾，因为顺乎形势，师出有名，故能化凶为吉。",
  career="阻力很大，困难很多，处于激烈的竞争状态，必与他人密切合作，谨小慎微，行为果断，切忌盲目妄动，适度即可，注意保全自己。机动灵活，严于律已。从容沉着对付一切，必能成功。", business="已有一定的积蓄，可以从事大的营销活动，但必卷入激烈商战，以刚毅顽强的精神和高尚的商业道德，辅以灵活的方法，勿贪图小利，勿掉以轻心，加强与他人的沟通，必可摆脱困境，化险为夷。",
  fame="具备很好的条件，但须有正确的引导，务必严格要求自己，克服不利因素的干扰，经过扎实努力，必可名利双全。", travel="“行险而顺。”虽有可能遇到麻烦，但结果一定十分顺利，可放心出行。", marriage="慎重、专注，否则会陷入“三角”纠纷。痴情追求可以达到目的。",
  decision="天资聪颖，性格灵活，具有坚强的意志，对事业执着追求，迎难而进。可成就大事业。喜竞争，善争辩，富有冒险精神，不免带来麻烦，务老成持重，不贪功，以中正为要。" },
  ["风水涣"] = { index="第59卦", name="风水涣", shortName="涣卦", subtitle="拯救涣散", rating="下下卦",
  xiang="隔河望见一锭金，欲取岸宽水又深，指望资财难到手，尽夜资财枉费心。", summary="这个卦是异卦（下坎上巽）相叠。风在水上行，推波助澜，四方流溢。涣，水流流散之意。象征组织和人心涣散，必用积极的手段和方法克服，战胜弊端，挽救涣散，转危为安。",
  career="处于比较困难的地步，主要是因为人心不齐。要采取强有力的办法，求得安定团结。其中，最为重要的是坚持正道，秉持大公无私的精神，收人心以聚涣散。", business="市场状况混乱，方向不明。适当的冒险是完全必要的。但必须公正无私，克制私欲。争取有实力者的合作和支援也是完全有必要的。",
  fame="必须静下心来努力学习和提高知识水平，增加才干。涣散的形势必须进行治理，这需要多方面的人才。前途是光明的，关键取决于个人的努力。", travel="平安无事，水路更顺利。", marriage="只要双方都抱着纯正的目的，一定美满成功。",
  decision="为了开拓事业，必须使用积极的手段，克服和战胜内部不团结的弊病。首先自己要除私心，牺牲小我，完成大我。切莫介入是非争端之中。这样，可以重新获得安定的局面。在良好的环境里，各项事业前途光明。" },
  ["火水未济"] = { index="第64卦", name="火水未济", shortName="未济卦", subtitle="事业未竟", rating="中下卦",
  xiang="离地着人几丈深，是防偷营劫寨人，后封太岁为凶煞，时加谨慎祸不侵。", summary="这个卦是异卦（下坎上离）相叠 。离为火，坎为水。火上水下，火势压倒水势，救火大功未成，故称未济。《周易》以乾坤二卦为始，以既济、未济二卦为终，充分反映了变化发展的思想。",
  career="处于最后的关键时刻，成功与否就在眼前。因此务必不可掉以轻心。自我节制非常重要，坚持到底，必要时也可能慎重地进行适度冒险，以成就事业。", business="市场处于大变动的前夕，前景如何尚不明显。这是最为艰苦的时期，头脑必冷静，切勿冒险，不可行动过度，适度节制，观察动向，决定行动。",
  fame="长期的努力和追求即会有结果。在成败的关键时刻应泰然自若，听天由命，顺其自然。", travel="积极行动，十分有利。", marriage="已经渡过了困难阶段，再慎重地加把劲，会有美满的结果。",
  decision="此卦的意思是“未完成”，表明前途无量，有充分发展的可能。因此，必须坚持中正的原则，以明智、中庸、诚信、谦逊的态度，成就事业。面对人生，唯有勤勤恳恳，极力尽人事，听天命，不必过分计较成功与否。" },
  ["坎为水"] = { index="第29卦", name="坎为水", shortName="坎卦", subtitle="行险用险", rating="下下卦",
  xiang="一轮明月照水中，只见影儿不见踪，愚夫当财下去取，摸来摸去一场空。", summary="这个卦是同卦（下坎上坎）相叠。坎为水、为险，两坎相重，险上加险，险阻重重。一阳陷二阴。所幸阴虚阳实，诚信可豁然贯通。虽险难重重，却方能显人性光彩。",
  career="陷入重重艰难险阻之中，险况丛生。既不得冒险，也不可束手待毙，应以积极态度，努力创造条件，改变处境，化险为夷。务必实心实意，充满信心，不图侥幸，不辞艰险，宜静观待变，运用智慧，突破险境，转危为安。", business="十分不利，甚至陷入面临破产的境地，但内心应沉着踏实，保持头脑冷静，身陷险境而心不陷，勿轻举妄动，先求自保以观变，把握时机以脱险。",
  fame="不为他人理解，怀才不遇。不可自暴自弃。不改初衷，泰然自若，循序渐进，终可为人理解和发现。", travel="大胆外出，另辟新路，必有所成，且得到他人相助。", marriage="多遭不利，应冷静分析原因，积极改变自身条件。双方同舟共济，共渡难关。",
  decision="不幸。然而是转运前的考验。只要能不因困境而失常，且不图侥幸，保持信心，勿自陷险境。镇定自若，不轻举妄动，洞察时机，必可转危为安，成出险之功。" },
  ["雷水解"] = { index="第40卦", name="雷水解", shortName="解卦", subtitle="柔道致治", rating="中上卦",
  xiang="目下月令如过关，千辛万苦受熬煎，时来恰相有人救，任意所为不相干。", summary="这个卦是异卦（下坎上震）相叠。震为雷、为动；坎为水、为险。险在内，动在外。严冬天地闭塞，静极而动。万象更新，冬去春来，一切消除，是为解。",
  career="元气初复，宜休养生息，安静平易为佳，宜宽宜和。当准备就绪则应立即行动，争取主动，不可拖廷，所往必有功利。但切勿贪得无厌。克勤克俭，刚柔相济，以柔为主。远辟小人，团结君子，相互依托，共成事业。", business="行动贵神速，积极而为，方可摆脱险境。行商宜循正道，切勿招摇过市。此乃愚蠢行动，必自招灾祸。",
  fame="初出茅庐，应继续充实自己。待机行动。尤应远小人近君子和有才德的人，以期迅速提高自己。", travel="一旦准备充分，立即行动，捷足先登必有所获。", marriage="应适时进行。夫妻和衷共济，可家庭和睦，免除灾难。",
  decision="稳妥为宜，亦不应冒险，因一切尚在元气初复阶段。为争取大发展，务必宽以待人，以柔致治，广交贤者，遣散小人，以中庸、正直的方式，张驰结合的手段，开拓方兴未艾的事业。" },
  ["山水蒙"] = { index="第4卦", name="山水蒙", shortName="蒙卦", subtitle="启蒙奋发", rating="中下卦",
  xiang="卦中爻象犯小耗，君子占之运不高，婚姻合伙有琐碎，做事必然受苦劳。", summary="这卦是异卦（下坎上艮 ）相叠，艮是山的形象，喻止；坎是水的形象，喻险。卦形为山下有险，仍不停止前进，是为蒙昧，故称蒙卦。但因把握时机，行动切合时宜，因此，具有启蒙和通达的卦象。",
  career="事业开始，混乱无序，危机四伏，以勇敢坚毅的行动可以扭转局面。然而必须接受严格教育，培养这种奋发图强的精神。务必脚踏实地，最忌好高骛远，否则会陷入孤立无援的境地。", business="务必小心谨慎，不得急功近利，尤其应树立高尚的商业道德，以良好的信誉提高竞争力而取胜。",
  fame="必须接受良好的基础教育，陶冶情操。且动机纯正，可以达到目的。", travel="等候有利时机再行动，等待期间应积极做准备。", marriage="注意考察对方品德，不可以金钱为诱铒。夫妻需相互宽容、理解。",
  decision="有时会陷入迷惘困顿的境地，加上胆小、不果断，往往误事。如能接受长辈的教诲，甚至严酷的考验，抛弃疑惧的心理，等待适当时机，必然一帆风顺。" },
  ["天水讼"] = { index="第6卦", name="天水讼", shortName="讼卦", subtitle="慎争戒讼", rating="中下卦",
  xiang="心中有事事难做，恰是二人争路走，雨下俱是要占先，谁肯让谁走一步。", summary="这个卦是异卦（下坎上乾）相叠。同需卦相反，互为“综卦”。乾为刚健，坎为险陷。刚与险，健与险，彼此反对，定生争讼。争讼非善事，务必慎重戒惧。",
  career="起初顺利，有利可图，继而受挫，务必警惕，慎之又慎，不得固执已见，极力避免介入诉讼纠纷的争执之中。与其这样，不如退而让人，求得化解，安于正理，可免除意外之灾。陷入争讼，即使获胜，最后还得失去，得不偿失。", business="和气生财，吃亏是福。切勿追求不义之财。商业谈判坚持公正公平、互利的原则，尽量避免发生冲突。这样，会有好结果。",
  fame="不利。自己尚缺乏竞争实力，应坚守纯正，隐忍自励，自强自勉，切莫逞强。依靠有地位的人的帮助，及早渡过难关。", travel="途中多有变故，宜改日出行。", marriage="虽不尽人意，倒也般配，彼此理解，未尝不可。双方应以温和的方式处理生活。",
  decision="争强好胜，不安于现状，为改变命运和超越他人而奋斗。头脑聪颖，反应敏捷，有贵人相助。但缺乏持之以恒的毅力，容易露出锋芒，得罪他人，带来诉讼之灾。宜承认现实，顺其自然，知足，适可而止。接受教训，引以为戒，可功成名就。" },
  ["泽水困"] = { index="第47卦", name="泽水困", shortName="困卦", subtitle="困境求通", rating="中上卦",
  xiang="时运不来好伤怀，撮上押去把梯抬，一筒虫翼无到手，转了上去下不来。", summary="这个卦是异卦（下坎上兑）相叠。兑为阴为泽喻悦；坎为阳为水喻险。泽水困，陷入困境，才智难以施展，仍坚守正道，自得其乐，必可成事，摆脱困境。",
  career="境况十分不佳，遭受到很大的困难。人生面临巨大的考验，如采取不正当的手段，会愈陷愈深。相反，如身陷困逆境地而不失节操，自勉自坚，泰然处之。不失其志。终能成事。", business="面临激烈竞争，很有破产的可能。切勿失望，而应在困境中奋斗。为此，只能靠平日加强修养。认真反省自己的行为，总结教训，重新奋起，但也不宜浮躁，应缓慢而进。同时，更要警惕因致富发财，得意忘形而陷入新的困境。",
  fame="欲速则不达。应以谦虚的态度，缓慢前进，尤应有坚定的志向，唯有志才能促成事业的成功。", travel="困难多，慎重考虑。", marriage="以乐观态度冷静处理，尤应注重人品。",
  decision="聪明智慧，但怀才不遇。若不因困境而失去信心，坚持努力上进，放弃侥幸心理，锲而不舍，虽不一定能守全实现自己的理想，但终会有所成。" },
}
